mapper.select:
SELECT COST_ID AS COST_ID, TARGET_TYPE_CD AS TARGET_TYPE_CD, TARGET_ID AS TARGET_ID,
       PERIOD_YM AS PERIOD_YM, SCENARIO_CD AS SCENARIO_CD, COST_TYPE_CD AS COST_TYPE_CD,
       AMOUNT AS AMOUNT, CURRENCY_CD AS CURRENCY_CD, REMARK AS REMARK
  FROM TB_IF_COST_PILOT
 WHERE TARGET_TYPE_CD = #{targetTypeCd} AND TARGET_ID = #{targetId}
   AND PERIOD_YM = #{periodYm}
AND SCENARIO_CD = #{scenarioCd}
 ORDER BY SCENARIO_CD, COST_TYPE_CD, COST_ID

mapper.insert:
INSERT INTO TB_IF_COST_PILOT (
  COST_ID, TARGET_TYPE_CD, TARGET_ID, PERIOD_YM, SCENARIO_CD, COST_TYPE_CD,
  AMOUNT, CURRENCY_CD, REMARK, REG_USER_ID, REG_DTM
) VALUES (
  #{costId}, #{targetTypeCd}, #{targetId}, #{periodYm}, #{scenarioCd}, #{costTypeCd},
  #{amount}, #{currencyCd}, #{remark}, #{regUserId}, #{regDtm}
)
